// Run with: node bundle-drawings.js   (re-run whenever you add/remove drawings)
//
// By default it reads  Startup_Drawings/Desktop_Drawings  and
// Startup_Drawings/Mobile_Drawings  (next to this file). If your JSON folders
// live somewhere else, pass them as arguments:
//
//   node bundle-drawings.js <desktop-folder> <mobile-folder>
//
// Converts the drawing JSONs in Startup_Drawings/ into small .js files so the
// site works without a server (file://) AND each visit only downloads ONE
// random drawing instead of all of them:
//
//   drawings/desktop-0.js, desktop-1.js, …   one file per drawing
//   drawings/mobile-0.js,  mobile-1.js,  …
//   drawings-manifest.js                      how many of each exist
//
// index.html loads only drawings-manifest.js; script.js then picks a random
// number below that count and loads that single file.

const fs = require('fs');
const path = require('path');

const [desktopArg, mobileArg] = process.argv.slice(2);
const folders = {
  desktop: desktopArg ? path.resolve(desktopArg) : path.join(__dirname, 'Startup_Drawings', 'Desktop_Drawings'),
  mobile:  mobileArg  ? path.resolve(mobileArg)  : path.join(__dirname, 'Startup_Drawings', 'Mobile_Drawings'),
};

for (const [kind, folder] of Object.entries(folders)) {
  if (!fs.existsSync(folder) || !fs.statSync(folder).isDirectory()) {
    console.error(`✗ ${kind} folder not found: ${folder}\n` +
                  `  Pass your JSON folders explicitly:  node bundle-drawings.js <desktop-folder> <mobile-folder>`);
    process.exit(1);
  }
}
const outDir = path.join(__dirname, 'drawings');

// Coordinates are stored as fractions of viewport width/height, so 4 decimal
// places is already sub-pixel precision on any real screen (<0.2px even at
// 2000px wide) — rounding to 4 digits cuts file size substantially with zero
// visible difference.
const PRECISION = 4;

const roundDrawing = (drawing) =>
  drawing.map(stroke => ({
    points: stroke.points.map(p => ({
      t: p.t,
      x: Math.round(p.x * 10 ** PRECISION) / 10 ** PRECISION,
      y: Math.round(p.y * 10 ** PRECISION) / 10 ** PRECISION,
    })),
  }));

// Remove only the files this script generated earlier (desktop-3.js, …) so
// deleted drawings don't linger — anything else in the folder is left alone.
fs.mkdirSync(outDir, { recursive: true });
for (const f of fs.readdirSync(outDir)) {
  if (/^(desktop|mobile)-\d+\.js$/.test(f)) fs.rmSync(path.join(outDir, f));
}

const manifest = {};
let totalBytes = 0;

for (const [kind, folder] of Object.entries(folders)) {
  const files = fs.readdirSync(folder).filter(f => f.endsWith('.json')).sort();
  if (files.length === 0) {
    console.error(`✗ No .json files in the ${kind} folder: ${folder}`);
    process.exit(1);
  }

  files.forEach((file, i) => {
    const data = JSON.parse(fs.readFileSync(path.join(folder, file), 'utf8'));
    // No whitespace in the JSON — comments stay for humans reading the file.
    const output = `// Auto-generated by bundle-drawings.js — do not edit manually\n` +
                   `window.__introDrawing = ${JSON.stringify(roundDrawing(data))};\n`;
    fs.writeFileSync(path.join(outDir, `${kind}-${i}.js`), output);
    totalBytes += Buffer.byteLength(output);
  });

  manifest[kind] = files.length;
  console.log(`${kind}: ${files.length} drawings`);
}

fs.writeFileSync(
  path.join(__dirname, 'drawings-manifest.js'),
  `// Auto-generated by bundle-drawings.js — do not edit manually\nconst DRAWINGS_MANIFEST = ${JSON.stringify(manifest)};\n`
);

console.log(`✓ drawings/ (${(totalBytes / 1024).toFixed(0)} KB total, one random file loaded per visit) + drawings-manifest.js created`);
